    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("ได้ยินเสียงไก่หรือลา", "โอ้อัลลอฮ์ ฉันขอความกรุณาจากพระองค์ (ไก่) - ฉันขอความคุ้มครองต่ออัลลอฮ์ให้พ้นจากชัยฏอน ผู้ถูกสาปแช่ง (ลา)", "เมื่อได้ยินไก่ตัวหนึ่งร้องขอความโปรดปรานจากอัลลอฮ์ เมื่อได้ยินเสียงลาร้องขอความคุ้มครองจากชัยฏอน", "ไก่เห็นเทวดา และลาเห็นปีศาจ"),
        "dua_something_liked" to DuaText("การเห็นสิ่งอันน่าชื่นชม (กับตาปีศาจ)", "สิ่งที่อัลลอฮ์ทรงประสงค์ โอ้อัลลอฮฺ โปรดประทานความจำเริญด้วย", "เมื่อเห็นสิ่งอันน่าชื่นชมของผู้อื่น จงอธิษฐานขอพร", "สวดมนต์ขอพรป้องกันตาปีศาจ"),
        "dua_sell_buy_debt_repaid" to DuaText("เมื่อชำระหนี้", "ขออัลลอฮ์ทรงอวยพรคุณในครอบครัวและความมั่งคั่งของคุณ", "สำหรับผู้ให้กู้เมื่อชำระหนี้", "การตอบแทนเงินกู้คือการขอบคุณและการชำระคืน"),
        "dua_talbiyah" to DuaText("ตัลบียาห์", "ฉันอยู่นี่ โอ้อัลลอฮ์ ฉันอยู่นี่ ฉันอยู่นี่ คุณไม่มีคู่ ฉันอยู่นี่ การสรรเสริญ พระพร และการครอบครองทั้งหมดเป็นของพระองค์อย่างแน่นอน คุณไม่มีคู่ครอง", "ดังหลังจากเข้าอิหฺรอมแล้ว", "ตราสัญลักษณ์ของฮัจญ์และอุมเราะห์"),
        "dua_yamani_hajar" to DuaText("ระหว่างรุกห์ ยามานี และฮาจาร์ อัสวัด", "พระเจ้าของเรา โปรดประทานความดีแก่เราในโลกนี้และความดีในปรโลก และโปรดปกป้องเราให้พ้นจากการลงโทษแห่งไฟนรก", "ในเตาวาฟ ระหว่างมุมเยเมนและหินดำ", "พระศาสดา ﷺ ท่องสิ่งนี้ ณ สถานที่แห่งนี้ในเตาวาฟ"),
        "dua_safa_marwa" to DuaText("เกี่ยวกับเศาะฟาและมัรวะฮฺ", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจนั้นเป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียว พระองค์ทรงปฏิบัติตามพระสัญญาของพระองค์ ช่วยผู้รับใช้ของพระองค์ และเอาชนะสมาพันธรัฐเพียงลำพัง", "ปีน Safa และหันหน้าไปทาง Qiblah (สามครั้ง)", "dhikr ของศาสดา ﷺ บน Safa และ Marwah"),
        "dua_arafah" to DuaText("Dua ที่ดีที่สุดของวันอารอฟะห์", "ไม่มีผู้ใดควรได้รับการสักการะนอกจากอัลลอฮ์ผู้เดียวโดยไม่มีภาคีใด ๆ อำนาจนั้นเป็นของพระองค์ และการสรรเสริญเป็นของพระองค์ และพระองค์ทรงมีอำนาจเหนือทุกสิ่ง", "วันอารอฟะห์ - ดุอาที่ดีที่สุด", "ดุอาที่ดีที่สุดคือดุอาแห่งวันอารอฟะห์ และคำพูดที่ดีที่สุดคือสิ่งเหล่านี้"),
        "dua_takbeer_tashreeq" to DuaText("ตั๊กเบียร์อีตัชรีก", "อัลลอฮ์นั้นยิ่งใหญ่ อัลลอฮ์นั้นยิ่งใหญ่ที่สุด ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์ อัลลอฮ์นั้นยิ่งใหญ่ อัลลอฮ์นั้นยิ่งใหญ่ และการสรรเสริญทั้งมวลเป็นของอัลลอฮฺ", "หลังจากการละหมาดบังคับทุกครั้งตั้งแต่ฟัจร์ 9 ซุลฮิจญะฮ์ ถึง อัสริ 13 ซุลฮิจญะห์", "รายงานจากอะลีและอิบนุ มัสอูด (RA) — วาจิบ ตามรายงานของฮานาฟิส"),
        "dua_zamzam" to DuaText("ดื่มซัมซัม", "โอ้อัลลอฮ์ ฉันขอความรู้ที่เป็นประโยชน์ การจัดเตรียมอันอุดมสมบูรณ์ และการรักษาโรคภัยไข้เจ็บทุกชนิด", "เมื่อดื่มซัมซัม จงขอดุอาอ์ตามสิ่งที่คุณตั้งใจ", "ซัมซัมมีไว้สำหรับทุกสิ่งที่เมา (อิบนุ มาญะฮ์ 3062)"),
        "dua_q_ma_khalaqta_batila" to DuaText("สะท้อนถึงการสร้างสรรค์", "พระเจ้าของเรา พระองค์ไม่ได้ทรงสร้างทั้งหมดนี้โดยเปล่าประโยชน์ มหาบริสุทธิ์แห่งพระองค์ โปรดปกป้องเราจากการลงโทษแห่งไฟ", "ดุอาอฺของบรรดาผู้ไตร่ตรองถึงการสร้างชั้นฟ้าทั้งหลายและแผ่นดิน", "ดุอาอ์ผู้มีความเข้าใจ (อุลลุลอัลบับ)"),
        "dua_q_sami_na_munadiyan" to DuaText("เราได้ยินผู้เรียกสู่ศรัทธา", "ข้าแต่พระเจ้าของเรา เราได้ยินเสียงผู้เรียกร้องศรัทธากล่าวว่า จงศรัทธาต่อพระเจ้าของท่าน แล้วเราก็ศรัทธา พระเจ้าของเรา โปรดอภัยบาปของเรา ขอทรงขจัดความชั่วของเราไปจากเรา และโปรดให้เราตายร่วมกับผู้ชอบธรรม", "ดุอาอ์เพื่อความศรัทธาและการตายในหมู่คนชอบธรรม", "ดุอาอฺเพื่อการอภัยโทษและการสิ้นสุดที่ดี"),
        "dua_q_atina_ma_waadtana" to DuaText("ให้สิ่งที่คุณสัญญาไว้กับเรา", "พระเจ้าของเรา โปรดประทานแก่เราตามที่พระองค์ทรงสัญญาไว้ผ่านทางศาสนทูตของพระองค์ และอย่าทำให้พวกเราอับอายในวันฟื้นคืนชีพ แท้จริงพระองค์ไม่ได้ผิดสัญญาของพระองค์", "ให้พ้นจากความอับอายในวันฟื้นคืนชีพ", "แสวงหาเกียรติในปรโลก"),
        "dua_q_israfana" to DuaText("ยกโทษให้กับส่วนเกินของเรา", "พระเจ้าของเรา โปรดอภัยบาปของเราและการกระทำที่เกินเลยของเรา โปรดทำให้เท้าของเรามั่นคง และช่วยเราต่อสู้กับกลุ่มผู้ปฏิเสธศรัทธา", "ดุอาอฺของสหายของศาสดาพยากรณ์รุ่นก่อนๆ", "ดุอาอ์เพื่อความแน่วแน่และการให้อภัย"),
        "dua_q_jamiun_nas" to DuaText("คุณจะรวบรวมมนุษยชาติ", "ข้าแต่พระเจ้าของเรา แท้จริงพระองค์จะทรงรวบรวมมวลมนุษย์ในวันที่ไม่มีข้อกังขาใด ๆ แท้จริงอัลลอฮฺจะไม่ทรงผิดสัญญาของพระองค์", "ยืนยันความแน่นอนในวันฟื้นคืนชีพ", "ดุอาอฺของผู้ที่มีพื้นฐานอันมั่นคงในความรู้"),
        "dua_q_maash_shahidin" to DuaText("เขียนถึงเราในหมู่พยาน", "พระเจ้าของเรา เราศรัทธาแล้ว ดังนั้นจงเขียนพวกเราไว้ในหมู่พยานด้วย", "ดุอาอฺของผู้ที่ยอมรับความจริงและศรัทธา", "ดุอาเพื่อการยอมรับความศรัทธาของตน"),
        "dua_q_la_tajalna_zalimin" to DuaText("ไม่ใช่กับคนทำผิด", "พระเจ้าของเรา โปรดอย่าทรงให้เราอยู่ร่วมกับกลุ่มผู้อธรรม", "ดุอาอฺของชาวอัลอะเราะฟ.", "ให้พ้นจากชะตากรรมของผู้กระทำความผิด"),
        "dua_q_tawaffana_muslimin" to DuaText("ความอดทนและความตายในฐานะมุสลิม", "พระเจ้าของเรา โปรดประทานความอดทนแก่เรา และโปรดให้เราตายในฐานะมุสลิมด้วย", "ดุอาของนักมายากลของฟาโรห์เมื่อพวกเขาศรัทธา", "ความอดทนในการทดลองและการสิ้นสุดเมื่อศรัทธา"),
        "dua_q_la_tajalna_fitnah" to DuaText("ไม่ใช่การทดลองสำหรับผู้กดขี่", "เราขอมอบหมายต่ออัลลอฮ์ พระเจ้าของเรา ขออย่าทรงให้เราเป็นการทดสอบแก่กลุ่มชนผู้อธรรม และโปรดช่วยเราด้วยความเมตตาของพระองค์จากกลุ่มผู้ปฏิเสธศรัทธาด้วย", "ดุอาอฺของชาวมูซา (AS)", "ดุอาเพื่อช่วยเหลือจากการกดขี่และผู้กดขี่"),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua ของ Nuh (AS) เพื่อการให้อภัย", "ข้าแต่พระเจ้าของฉัน ข้าพระองค์ขอความคุ้มครองต่อพระองค์จากการทูลถามพระองค์ในสิ่งที่ข้าพระองค์ไม่มีความรู้ และเว้นแต่พระองค์จะทรงอภัยโทษและเมตตาฉัน ฉันก็จะอยู่ในหมู่ผู้ขาดทุน", "ดุอาการกลับใจของท่านศาสดานูห์ (AS)", "บทเรียนการถามอย่างมีมารยาท"),
        "dua_q_mudkhala_sidq" to DuaText("ทางเข้าและทางออกของความจริง", "พระเจ้าของฉัน โปรดให้ฉันเข้าด้วยความจริง และออกไปด้วยความจริง และโปรดประทานอำนาจสนับสนุนจากพระองค์แก่ฉันด้วย", "ก่อนเข้างานใหม่ บ้าน หรือสถานที่ใหม่", "ดุอาอฺสอนท่านศาสดา ﷺ ในช่วงเวลาฮิจเราะห์"),
        "dua_q_la_tadharni_fardan" to DuaText("ดุอาอฺซะกะริยา (AS) — อย่าทิ้งฉันไว้ตามลำพัง", "พระเจ้าของฉัน โปรดอย่าทิ้งฉันไว้ตามลำพัง และพระองค์ทรงเป็นผู้สืบทอดที่ดีที่สุด", "สำหรับผู้ที่กำลังมองหาเด็ก.", "โดยดุอานี้อัลลอฮ์ทรงประทานยะห์ยา (AS)"),
        "dua_q_munzalan_mubarakan" to DuaText("สถานที่ลงจอดอันศักดิ์สิทธิ์", "พระเจ้าของฉัน โปรดให้ฉันลงจอด ณ ที่อันประเสริฐ และพระองค์คือผู้ดีที่สุดในบรรดาผู้ที่นำขึ้นบก", "เมื่อจะย้ายไปบ้านใหม่หรือแวะที่ไหนสักแห่ง — ดุอาอ์ (AS)", "ดุอาอฺขอพรในสถานที่ใหม่"),
        "dua_q_amanna_faghfir" to DuaText("เราเชื่อ ดังนั้นโปรดยกโทษให้เราด้วย", "พระเจ้าของเรา เราศรัทธาแล้ว ดังนั้นโปรดอภัยโทษพวกเราและเมตตาพวกเราด้วย และพระองค์คือผู้ประเสริฐที่สุดในบรรดาผู้เมตตา", "ดุอาอฺแห่งบ่าวผู้ชอบธรรมของอัลลอฮฺ", "Dua ที่ครอบคลุมสำหรับการให้อภัยและความเมตตา"),
        "dua_q_isrif_jahannam" to DuaText("หลีกเลี่ยงการลงโทษของนรก", "พระเจ้าของเรา โปรดทรงโปรดให้พ้นจากการลงโทษแห่งนรกไปจากเราเถิด แท้จริงการลงโทษของมันนั้นคงอยู่ถาวร แท้จริงแล้วมันเป็นถิ่นฐานและที่อยู่อาศัยที่ชั่วร้าย", "ดุอาแห่งบ่าวของพระผู้ทรงเมตตาเสมอ (อิบัด อัร-เราะห์มาน)", "ดุอาอ์กุรอานเพื่อขอความคุ้มครองจากนรก"),
        "dua_q_hab_li_hukman" to DuaText("ดุอาอิบราฮิม (AS) — ปัญญาและญานนาห์", "พระเจ้าของข้าพระองค์ โปรดประทานสติปัญญาแก่ข้าพระองค์ และร่วมกับข้าพระองค์ร่วมกับบรรดาผู้ชอบธรรม ทรงให้ข้าพระองค์ได้รับการยกย่องในหมู่คนรุ่นต่อๆ ไป และทรงให้ข้าพระองค์เป็นหนึ่งในผู้รับมรดกแห่งสวนแห่งความสุข", "ขอปัญญาคณะผู้ชอบธรรมและสวรรค์", "ดุอาที่ครอบคลุมของอิบราฮิม (AS)"),
        "dua_q_lut_najjini_ahli" to DuaText("Dua of Lut (AS) — ช่วยครอบครัวของฉัน", "พระเจ้าของฉัน โปรดช่วยฉันและครอบครัวให้พ้นจากสิ่งที่พวกเขากระทำกันด้วย", "ปกป้องครอบครัวของตนจากสภาพแวดล้อมแห่งความชั่วร้าย", "การปกป้องครอบครัวจากความชั่วร้าย"),
        "dua_q_sulaiman_awzini" to DuaText("ดุอาอฺสุไลมาน (AS) เพื่อความกตัญญู", "พระเจ้าของข้าพระองค์ โปรดช่วยให้ข้าพระองค์สำนึกคุณต่อความโปรดปรานของพระองค์ที่พระองค์ประทานแก่ข้าพระองค์และพ่อแม่ของข้าพระองค์ และให้กระทำความดีที่พระองค์พอพระทัย และยอมรับข้าพระองค์ด้วยความเมตตาของพระองค์ในหมู่ผู้รับใช้ที่ชอบธรรมของพระองค์", "เพื่อความสามารถในการสำนึกบุญคุณต่อคำอวยพร", "ดุอาอฺขอบคุณสุไลมาน (AS)"),
        "dua_q_musa_zalamtu" to DuaText("Dua ของมูซา (AS) — ฉันได้ทำผิดต่อตัวเอง", "พระเจ้าของฉัน ฉันได้ทำผิดต่อตัวเอง ดังนั้นโปรดยกโทษให้ฉันด้วย", "กลับใจทันทีหลังจากทำผิดพลาด", "อัลลอฮ์ทรงอภัยโทษมูซา (AS)"),
        "dua_q_musa_najjini" to DuaText("Dua ของมูซา (AS) — ช่วยฉันให้พ้นจากผู้กดขี่", "พระเจ้าของฉัน โปรดช่วยฉันให้พ้นจากหมู่ชนผู้อธรรมด้วย", "เมื่อเกรงกลัวผู้กดขี่", "ดุอาอ์มูซา (AS) เมื่อออกจากอียิปต์"),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — การช่วยเหลือผู้ทุจริต", "ข้าแต่พระเจ้าของข้าพระองค์ โปรดช่วยข้าพระองค์ต่อสู้กับผู้คนที่ทุจริตด้วย", "เพื่อช่วยเหลือผู้เผยแพร่การคอรัปชั่น", "ดุอาอ์ของผู้ยึดมั่นในความจริง"),
        "dua_q_hab_li_salihin" to DuaText("Dua ของอิบราฮิม (AS) เพื่อเด็กที่ชอบธรรม", "พระเจ้าของฉัน โปรดประทาน (เด็ก) จากบรรดาผู้ทำความดีแก่ฉันด้วย", "ขอบุตรที่ชอบธรรม", "โดยดุอาอิสมาอิล (AS) นี้ได้รับ"),
        "dua_q_wasita_kulla_shay" to DuaText("Dua ของเทวดาที่ครองบัลลังก์", "พระเจ้าของเรา พระองค์ทรงครอบคลุมทุกสิ่งด้วยความเมตตาและความรู้ ดังนั้นโปรดอภัยให้กับผู้ที่กลับใจและปฏิบัติตามทางของพระองค์ และปกป้องพวกเขาจากการลงโทษในนรก", "เหล่าทูตสวรรค์ผู้ครองบัลลังก์จะขอดุอานี้แก่บรรดาผู้ศรัทธา", "ท่องโดยมีเจตนาให้รวมอยู่ในดุอาของเทวดา"),
        "dua_q_ikhwanina" to DuaText("สำหรับพี่น้องของเราที่อยู่ก่อนหน้าเรา", "พระเจ้าของเรา โปรดอภัยโทษแก่เราและพี่น้องของเราที่ศรัทธาก่อนหน้าเรา และอย่าทำให้จิตใจของเราขุ่นเคืองต่อผู้ที่ศรัทธา พระเจ้าของเรา พระองค์ทรงเมตตาและเมตตาจริงๆ", "ดุอาอ์สำหรับผู้ศรัทธาที่มาก่อนและเพื่อจิตใจที่สะอาด", "ดุอาอฺสำหรับสหายผู้สูงศักดิ์ (RA) และผู้ศรัทธารุ่นก่อนๆ"),
        "dua_q_alayka_tawakkalna" to DuaText("เราขอพึ่งท่าน (อิบรอฮีม อ.)", "ข้าแต่พระเจ้าของเรา เราขอมอบหมายต่อพระองค์ เราขอวิงวอนต่อพระองค์ และการกลับคืนสู่พระองค์ พระเจ้าของเรา โปรดอย่าทรงทำให้เราเป็นการทดสอบแก่บรรดาผู้ปฏิเสธศรัทธา และทรงอภัยโทษให้แก่เราด้วย พระเจ้าของเรา พระองค์ทรงเป็นผู้ทรงอำนาจ ผู้ทรงปรีชาญาณอย่างแท้จริง", "ดุอาอ์อิบรอฮีม (AS) และสหายของเขา", "ดุอาแห่งการพึ่งพาอัลลอฮ์และหันไปหาพระองค์"),
        "dua_q_atmim_nurana" to DuaText("ทำให้แสงของเราสมบูรณ์แบบ", "พระเจ้าของเรา ทรงทำให้แสงสว่างของเราสมบูรณ์แบบสำหรับเรา และทรงอภัยโทษให้เราด้วย แท้จริงแล้วพระองค์ทรงมีอำนาจเหนือทุกสิ่ง", "ดุอาอฺของผู้ศรัทธาในวันฟื้นคืนชีพ", "ขอแสงสว่างที่สิรัต"),
        "dua_q_asiya_baytan" to DuaText("ดุอาแห่งอาซิยา – บ้านในญานนาห์", "ข้าแต่พระเจ้าของฉัน โปรดสร้างบ้านในสวรรค์แก่ฉันใกล้พระองค์ โปรดช่วยฉันให้พ้นจากฟาโรห์และการกระทำของเขา และช่วยฉันให้พ้นจากหมู่ชนที่อธรรม", "ดุอาอฺอาซิยะ ภรรยาของฟาโรห์", "อัลลอฮ์ทรงทำให้เธอเป็นแบบอย่างแก่บรรดาผู้ศรัทธา"),
        "dua_adhan_response" to DuaText("ตอบสนองอาซาน", "ไม่มีอำนาจและไม่มีอำนาจใด ๆ เว้นแต่กับอัลลอฮ์", "ทำซ้ำสิ่งที่มูซซินพูด ที่ 'Hayya 'alas-salah' และ 'hayya 'alal-falah' พูดแบบนี้", "ใครตอบสนองจากใจจะได้เข้าสวรรค์"),
        "dua_adhan_shahadah" to DuaText("หลังจากชาฮาดาห์ของมุอัซซิน", "และฉันก็ขอเป็นพยานด้วยว่าไม่มีผู้ใดมีสิทธิที่จะได้รับการสักการะนอกจากอัลลอฮ์ ผู้เดียว โดยไม่มีภาคีใด ๆ และมูฮัมหมัด ﷺ เป็นผู้รับใช้และศาสนทูตของพระองค์ ฉันพอใจที่มีอัลลอฮ์เป็นพระเจ้า โดยมีมูฮัมหมัด ﷺ เป็นศาสนทูต และมีอิสลามเป็นศาสนา", "เมื่อได้ยินคำพยานแห่งศรัทธาของมูซซิน", "บาปของเขาได้รับการอภัยแล้ว"),
        "dua_istiftah_baid" to DuaText("ดุอาอฺเปิด: ห่างไกลจากบาป", "โอ้อัลลอฮ์ โปรดทรงทำให้ฉันห่างไกลจากบาปของฉัน เนื่องจากพระองค์ทรงทำให้ทิศตะวันออกอยู่ห่างจากตะวันตก โอ้อัลลอฮ์ โปรดทรงชำระฉันให้พ้นจากบาป ดังเช่นเสื้อผ้าสีขาวที่ชำระล้างสิ่งสกปรก โอ้อัลลอฮ์ โปรดชำระล้างบาปของฉันด้วยน้ำ หิมะ และลูกเห็บ", "หลังจากพิธีเปิดตักบีร (อาจกล่าวแทนเสนาก็ได้)", "พระศาสดา ﷺ ท่องสิ่งนี้ระหว่างตักบีร์และการบรรยาย"),
        "dua_hamdan_kathiran" to DuaText("คำสรรเสริญมากมายหลังจาก Ruku", "พระเจ้าของเรา การสรรเสริญเป็นของพระองค์ - การสรรเสริญอันอุดม บริสุทธิ์ และเปี่ยมสุข", "ภายหลังเสด็จขึ้นจากรุกูพร้อมกับ 'รับพนะ ลากัลฮัมด์'", "ทูตสวรรค์มากกว่าสามสิบองค์กำลังเร่งรีบเพื่อเป็นคนแรกที่จะบันทึกบันทึกนี้"),
    )
}
